import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { classifyTerminalLifecycleOwnership } from '../../../_vendor/core/dist/broker/historical-work-admission-attestation.js';
import { buildFrameworkTempClaimCommand, buildFrameworkStaleCleanupCommand, createFrameworkModeStatus, inspectAutoGeneratedResidue, isAdopterInfrastructureSyncCommit, isFrameworkStaleLockReleasable, readActiveCloseCommitWindows } from '../../framework-development.js';
import { detectCrossTaskMutation, recordIncidentFlag } from '../../../_vendor/core/dist/broker/cross-task-mutation-guard.js';
import { gitHeadEvidencePaths } from '../../git-head-evidence.js';
import { makeResult, message } from '../../shared.js';
import { diagnoseTaskDirectionLockAllowedFiles, isPlanningMirrorPath, readActiveTaskDirectionLocks } from '../../task-direction.js';
import { isPathAllowedByScope, readActiveQuickfixLock } from '../../work-channels.js';
import { isReleasedGeneratedBundleSafeToClean, readGeneratedResidueTaskDisposition, reconcileReleasedResidueReport } from '../../tasks/generated-residue-policy.js';
import { resolvePreCommitResidueCandidates } from './residue-candidates.js';
import { consumeCloseTransactionHookReceipt } from './close-transaction-receipt.js';
import { buildTeamGateFindings } from './team-gate-findings.js';
import { inspectGitIndexAccess } from '../git-index-diagnostics.js';
import { normalizeOptionalText, readJsonText } from '../commit-range-guard.js';
import { buildBrokerResolutionDependencyDeferral, checkStageTimeCrossFileConsistency } from './cross-file-consistency.js';
import { buildCommitTaskFrameworkLockContext } from './framework-lock-context.js';
import { authorizesRunnerPublicationCloseCommit } from '../../framework-development/runner-publication-close-handoff.js';
import { buildPreCommitBlockingFindings, buildPreCommitFailureEnvelope, selectActionableResidueFindings } from './failure-envelope.js';
import { inspectTaskCardStatusChanges, readStagedChangedLineCount, readStagedFiles, scanEncoding, shouldWriteGitHeadEvidenceForStagedCommit, writeStagedGitHeadEvidence } from './input-state.js';
import { collectCloseCommitWindowPlanningMirrorFiles, collectFrameworkTempClaimAllowedFiles, collectStagedBatchCheckpointScopeFiles, collectTaskGovernedCommitAllowedFiles, inferTaskIdsFromStagedFiles, inspectCommitAttribution, inspectEmergencyUseAudit, inspectProtectedAtmStateChanges, inspectSameFileClaimOwnership, inspectTaskOpenImportBundleStagedArtifacts, isActionableManualResidue, isPathAllowedByTaskDirection, isResolutionAuthorizedCurrentTask, isTaskDirectionPreCommitExempt, resolveResidueTaskId, selectRelevantDirectionLocksForCommit, uniqueSorted } from './support.js';
export { inspectProtectedAtmStateChanges, isUnconsumedCloseWindowDeferralSnapshot } from './support.js';
export { authorizeBlockLifecycleRecordBridge } from './cross-task-admission.js';
import { authorizeBlockLifecycleRecordBridge, raiseCrossTaskMutationBlock } from './cross-task-admission.js';
export function runPreCommitHook(cwd) {
    const root = path.resolve(cwd);
    const explicitCommittingTaskId = typeof process.env.ATM_COMMIT_TASK_ID === 'string' ? process.env.ATM_COMMIT_TASK_ID.trim() : null;
    const stagedTaskIdsForContext = explicitCommittingTaskId ? [] : inferTaskIdsFromStagedFiles(readStagedFiles(root));
    const committingTaskIdForHook = explicitCommittingTaskId || (stagedTaskIdsForContext.length === 1 ? stagedTaskIdsForContext[0] : null);
    const scopedIndexActive = typeof process.env.GIT_INDEX_FILE === 'string' && process.env.GIT_INDEX_FILE.trim().length > 0;
    const crossTaskBlock = detectCrossTaskMutation(root, committingTaskIdForHook, 'pre-commit', scopedIndexActive ? readStagedFiles(root) : undefined);
    const hasTaskHistoryCrossTaskBlock = crossTaskBlock?.conflicts.some((entry) => entry.surface === 'task-history') ?? false;
    if (crossTaskBlock && hasTaskHistoryCrossTaskBlock && !isResolutionAuthorizedCurrentTask(root, committingTaskIdForHook, crossTaskBlock.conflictTaskId) && !authorizeBlockLifecycleRecordBridge(root, crossTaskBlock).authorized) {
        recordIncidentFlag(root, crossTaskBlock);
        raiseCrossTaskMutationBlock({ committingTaskId: committingTaskIdForHook, crossTaskBlock });
    }
    const commitIndexFinalized = process.env.ATM_COMMIT_INDEX_FINALIZED === '1';
    const residueCandidates = resolvePreCommitResidueCandidates(root, scopedIndexActive);
    const residueTaskId = resolveResidueTaskId(root);
    const residueReport = inspectAutoGeneratedResidue(residueTaskId, residueCandidates, root);
    const releasedBundleResidue = residueCandidates.filter((filePath) => /^\.atm\/history\/evidence\/[^/]+\.bundle-manifest\.json$/i.test(filePath)).map((filePath) => {
        const ownerTaskId = filePath.match(/^\.atm\/history\/evidence\/([^/]+)\.bundle-manifest\.json$/i)?.[1]?.toUpperCase() ?? null;
        const disposition = ownerTaskId ? readGeneratedResidueTaskDisposition(root, ownerTaskId) : null;
        return ownerTaskId && isReleasedGeneratedBundleSafeToClean(disposition) ? { path: filePath, verdict: 'auto-clean-safe', reason: 'Released-task bundle-manifest is disposable generated residue; lifecycle audit records remain preserved.', ownerTaskId, cleanupAction: 'remove' } : null;
    }).filter((entry) => Boolean(entry));
    const reconciledResidueReport = releasedBundleResidue.length === 0 ? residueReport : {
        ...residueReport,
        autoCleanSafe: [...residueReport.autoCleanSafe, ...releasedBundleResidue],
        blockAndExplain: residueReport.blockAndExplain.filter((entry) => !releasedBundleResidue.some((released) => released.path === entry.path)),
    };
    const transactionReconciledResidueReport = reconcileReleasedResidueReport(root, residueTaskId, reconciledResidueReport);
    // Pre-commit is an admission observer.  A safe-to-clean classification is
    // not authority to delete bytes owned by another lane or an interrupted run.
    // Cleanup remains an explicit governed disposition, while this hook reports
    // the candidates without mutating the live worktree or index.
    const autoCleanedResidue = [];
    const stagedFiles = readStagedFiles(root).filter((entry) => entry !== gitHeadEvidencePaths.legacyJson && entry !== gitHeadEvidencePaths.jsonl);
    const closeTransactionReceiptReuse = consumeCloseTransactionHookReceipt({
        root,
        taskId: committingTaskIdForHook,
        actorId: typeof process.env.ATM_COMMIT_ACTOR_ID === 'string' ? process.env.ATM_COMMIT_ACTOR_ID.trim() || null : null,
        invocationNonce: typeof process.env.ATM_CLOSE_TRANSACTION_RECEIPT_NONCE === 'string' ? process.env.ATM_CLOSE_TRANSACTION_RECEIPT_NONCE.trim() || null : null,
        commitSurface: typeof process.env.ATM_CLOSE_TRANSACTION_RECEIPT_SURFACE === 'string' ? process.env.ATM_CLOSE_TRANSACTION_RECEIPT_SURFACE.trim() || null : null,
        scopedIndexActive,
        closeWindowLock: readActiveCloseCommitWindows(root).find((entry) => entry.taskId === committingTaskIdForHook) ?? null,
        stagedFiles
    });
    const actionableResidueFindings = selectActionableResidueFindings({
        findings: [...transactionReconciledResidueReport.blockAndExplain, ...transactionReconciledResidueReport.manualReview.filter((entry) => isActionableManualResidue(entry.path))],
        stagedFiles,
        committingTaskId: residueTaskId,
        activeLockTaskIds: new Set(readActiveTaskDirectionLocks(root)
            .map((lock) => typeof lock.taskId === 'string' ? lock.taskId.trim().toUpperCase() : '')
            .filter(Boolean)),
        hasActiveClaim: (ownerTaskId) => {
            try {
                const taskDocument = JSON.parse(readFileSync(path.join(root, '.atm', 'history', 'tasks', `${ownerTaskId}.json`), 'utf8'));
                const claim = taskDocument.claim;
                return Boolean(claim) && String(claim.state ?? '') === 'active';
            }
            catch {
                return false;
            }
        },
        hasInactiveLifecycleOwner: (ownerTaskId) => {
            try {
                const taskDocument = JSON.parse(readFileSync(path.join(root, '.atm', 'history', 'tasks', `${ownerTaskId}.json`), 'utf8'));
                const status = String(taskDocument.status ?? '').trim().toLowerCase();
                const claim = taskDocument.claim;
                const claimState = claim ? String(claim.state ?? '').trim().toLowerCase() : '';
                const lockPath = path.join(root, '.atm', 'runtime', 'locks', `${ownerTaskId}.lock.json`);
                let lockReleased = true;
                if (existsSync(lockPath)) {
                    const lock = JSON.parse(readFileSync(lockPath, 'utf8'));
                    lockReleased = lock.released === true || lock.status === 'released';
                }
                return classifyTerminalLifecycleOwnership({ status, claimState, lockReleased }).decision === 'terminal';
            }
            catch {
                return false;
            }
        }
    });
    const gitIndexDiagnostic = inspectGitIndexAccess(root);
    const encodingReport = scanEncoding(root, stagedFiles);
    const frameworkStatus = createFrameworkModeStatus({
        cwd: root,
        files: stagedFiles,
        taskId: committingTaskIdForHook,
        actorId: process.env.ATM_COMMIT_ACTOR_ID
    });
    const allowAdopterInfrastructureSync = isAdopterInfrastructureSyncCommit(stagedFiles.length > 0 ? stagedFiles : frameworkStatus.changedFiles);
    const activeDirectionLocks = readActiveTaskDirectionLocks(root);
    const activeQuickfixLock = readActiveQuickfixLock(root);
    const taskGovernedCommitAllowedFiles = collectTaskGovernedCommitAllowedFiles(root, committingTaskIdForHook);
    // TASK-AAO-0136: collect close-commit-window allowedFiles (short-lived locks
    // opened by tasks close / tasks reconcile). These authorize landing the close
    // artifacts after the regular direction lock has already released.
    const activeCloseCommitWindows = readActiveCloseCommitWindows(root);
    const closeCommitWindowAllowedFiles = uniqueSorted(activeCloseCommitWindows.flatMap((win) => [
        ...win.allowedFiles,
        `.atm/history/tasks/${win.taskId}.json`,
        `.atm/history/evidence/${win.taskId}.json`,
        `.atm/history/evidence/${win.taskId}.bundle-manifest.json`,
        `.atm/history/evidence/${win.taskId}.closure-packet.json`,
        `.atm/history/task-events/${win.taskId}/**`
    ]));
    const closeCommitWindowPlanningMirrorFiles = collectCloseCommitWindowPlanningMirrorFiles(root);
    const relevantDirectionLocks = selectRelevantDirectionLocksForCommit({
        activeDirectionLocks,
        stagedFiles,
        committingTaskId: committingTaskIdForHook,
        taskGovernedCommitAllowedFiles,
        closeCommitWindowAllowedFiles,
        closeCommitWindowPlanningMirrorFiles
    });
    const directionLockAllowedFiles = uniqueSorted(relevantDirectionLocks.flatMap((lock) => lock.allowedFiles));
    const directionLockAllowedFilesDiagnoses = activeDirectionLocks
        .map((lock) => diagnoseTaskDirectionLockAllowedFiles(root, lock.taskId));
    const directionLockAllowedFilesMismatches = directionLockAllowedFilesDiagnoses.filter((entry) => entry.mismatches.length > 0);
    const checkpointClosedTaskAllowedFiles = collectStagedBatchCheckpointScopeFiles(root, stagedFiles);
    const checkpointCoversFrameworkCriticalFiles = frameworkStatus.criticalChangedFiles.length > 0
        && frameworkStatus.criticalChangedFiles.every((entry) => isPathAllowedByTaskDirection(entry, checkpointClosedTaskAllowedFiles));
    const directionLockCoversFrameworkCriticalFiles = frameworkStatus.criticalChangedFiles.length > 0
        && frameworkStatus.criticalChangedFiles.every((entry) => isPathAllowedByTaskDirection(entry, directionLockAllowedFiles));
    const frameworkTempClaimAllowedFiles = collectFrameworkTempClaimAllowedFiles(root);
    const frameworkTempClaimCoversFrameworkCriticalFiles = frameworkStatus.criticalChangedFiles.length > 0
        && frameworkStatus.criticalChangedFiles.every((entry) => isPathAllowedByTaskDirection(entry, frameworkTempClaimAllowedFiles));
    const runnerPublicationReceiptPath = committingTaskIdForHook
        ? path.join(root, '.atm', 'history', 'evidence', `${committingTaskIdForHook}.runner-sync-receipt.json`)
        : null;
    const runnerPublicationReceipt = runnerPublicationReceiptPath && existsSync(runnerPublicationReceiptPath)
        ? readJsonText(readFileSync(runnerPublicationReceiptPath, 'utf8'))
        : null;
    const runnerPublicationCoversFrameworkCriticalFiles = committingTaskIdForHook
        ? authorizesRunnerPublicationCloseCommit({
            taskId: committingTaskIdForHook,
            receipt: runnerPublicationReceipt,
            criticalChangedFiles: frameworkStatus.criticalChangedFiles
        })
        : false;
    const rawBlockingFrameworkIssues = frameworkStatus.blockers.filter((entry) => {
        if (entry === 'git-head-evidence-missing')
            return false;
        if (entry === 'active-framework-claim-required' && (checkpointCoversFrameworkCriticalFiles || directionLockCoversFrameworkCriticalFiles || frameworkTempClaimCoversFrameworkCriticalFiles || runnerPublicationCoversFrameworkCriticalFiles))
            return false;
        if (entry === 'closure-authority-belongs-to-target-repo' && allowAdopterInfrastructureSync)
            return false;
        return true;
    });
    const frameworkLockContext = buildCommitTaskFrameworkLockContext({
        blockers: rawBlockingFrameworkIssues,
        staleLocks: frameworkStatus.staleLocks,
        commitTaskId: process.env.ATM_COMMIT_TASK_ID,
        commitActorId: process.env.ATM_COMMIT_ACTOR_ID
    });
    const blockingFrameworkIssues = frameworkLockContext.blockers;
    const directionLockPlanningMirrorPaths = uniqueSorted(relevantDirectionLocks.flatMap((lock) => lock.planningMirrorPaths ?? []));
    const directionLockAllowsPlanningMirror = relevantDirectionLocks.some((lock) => lock.allowPlanningMirror === true);
    const taskOpenImportBundle = inspectTaskOpenImportBundleStagedArtifacts(root, stagedFiles);
    const directionLockDriftFiles = relevantDirectionLocks.length > 0 && !allowAdopterInfrastructureSync
        ? taskOpenImportBundle.ok
            ? []
            : stagedFiles
                .filter((entry) => !isTaskDirectionPreCommitExempt(entry))
                .filter((entry) => !isPathAllowedByTaskDirection(entry, directionLockAllowedFiles))
                .filter((entry) => !isPathAllowedByTaskDirection(entry, checkpointClosedTaskAllowedFiles))
                .filter((entry) => !isPathAllowedByTaskDirection(entry, frameworkTempClaimAllowedFiles))
                .filter((entry) => !isPathAllowedByTaskDirection(entry, taskGovernedCommitAllowedFiles))
                .filter((entry) => !isPathAllowedByTaskDirection(entry, closeCommitWindowAllowedFiles))
        : [];
    const planningMirrorDriftFiles = relevantDirectionLocks.length > 0 && !allowAdopterInfrastructureSync && directionLockPlanningMirrorPaths.length > 0 && !directionLockAllowsPlanningMirror
        ? stagedFiles
            .filter((entry) => !isTaskDirectionPreCommitExempt(entry))
            .filter((entry) => isPlanningMirrorPath(entry, directionLockPlanningMirrorPaths))
            .filter((entry) => !isPathAllowedByTaskDirection(entry, taskGovernedCommitAllowedFiles))
            .filter((entry) => !isPathAllowedByTaskDirection(entry, closeCommitWindowPlanningMirrorFiles))
        : [];
    const quickfixDriftFiles = activeQuickfixLock && !allowAdopterInfrastructureSync
        ? stagedFiles
            .filter((entry) => !isTaskDirectionPreCommitExempt(entry))
            .filter((entry) => !isPathAllowedByScope(entry, activeQuickfixLock.allowedFiles))
        : [];
    const quickfixFileLimitExceeded = activeQuickfixLock
        ? stagedFiles.filter((entry) => !entry.startsWith('.atm/')).length > activeQuickfixLock.maxFiles
        : false;
    const quickfixChangedLineCount = activeQuickfixLock
        ? readStagedChangedLineCount(root, stagedFiles.filter((entry) => !entry.startsWith('.atm/')))
        : 0;
    const quickfixLineLimitExceeded = activeQuickfixLock
        ? quickfixChangedLineCount > activeQuickfixLock.maxChangedLines
        : false;
    const isBrokerResolutionAuthorizedDependencyDeferral = buildBrokerResolutionDependencyDeferral(root, process.env.ATM_COMMIT_TASK_ID ?? null, process.env.ATM_COMMIT_BROKER_CONFLICT_RESOLUTION);
    const protectedStateReport = inspectProtectedAtmStateChanges(root, stagedFiles);
    const emergencyUseAuditReport = inspectEmergencyUseAudit(root, stagedFiles);
    const taskCardStatusReport = inspectTaskCardStatusChanges(root, stagedFiles);
    const commitAttributionReport = inspectCommitAttribution(root, stagedFiles);
    const explicitActorWarning = stagedFiles.length > 0 && !normalizeOptionalText(process.env.ATM_COMMIT_ACTOR_ID)
        ? message('warn', 'ATM_HOOK_COMMIT_ACTOR_NOT_EXPLICIT', 'No explicit commit actor was provided. Configure this editor/agent with its own actor identity instead of relying on repo default identity.', {
            clearStaleDefaultCommand: 'node atm.mjs identity clear --json',
            requiredCommand: 'node atm.mjs identity clear --json && node atm.mjs identity set --actor <actor-id> --editor <editor-id> --git-name "<git user.name>" --git-email "<git user.email>" --json',
            env: 'ATM_COMMIT_ACTOR_ID or ATM_ACTOR_ID'
        })
        : null;
    // TASK-CID-0024: same-file parallel claims are first-class. Multiple active
    // claims covering one staged file must not block by themselves; only
    // ambiguous staged ownership without steward/broker evidence blocks.
    const sameFileClaimReport = allowAdopterInfrastructureSync
        ? { ok: true, committingTaskId: null, committingClaimIntent: null, multiClaimFiles: [], stewardCoveredFiles: [], sharedWriteAdmission: null, findings: [] }
        : inspectSameFileClaimOwnership({
            cwd: root,
            stagedFiles,
            activeDirectionLocks: relevantDirectionLocks,
            exemptAllowedFileSets: [
                checkpointClosedTaskAllowedFiles,
                taskGovernedCommitAllowedFiles,
                closeCommitWindowAllowedFiles,
                frameworkTempClaimAllowedFiles
            ]
        });
    // A Git hook is a control-plane gate: it must only inspect the sealed staged
    // candidate and its directly-required authority. Repository-wide audits and
    // framework validator suites are execution-plane work, owned by taskflow
    // evidence, pre-push, and CI. Running them here made every commit wait on
    // unrelated task history and repeatedly revalidated one close transaction.
    const commandRuns = [];
    const failedValidatorRuns = [];
    const taskAuditFindings = [];
    const staleLocks = frameworkLockContext.staleLocks;
    const releasableStaleLock = staleLocks.find(isFrameworkStaleLockReleasable) ?? null;
    const baseClaimCommand = buildFrameworkTempClaimCommand(frameworkStatus.criticalChangedFiles, 'temporary framework maintenance before commit', releasableStaleLock?.actorId ?? null);
    const frameworkClaimCommand = blockingFrameworkIssues.includes('active-framework-claim-required')
        ? baseClaimCommand
        : blockingFrameworkIssues.includes('framework-stale-lock-cleanup-required') && releasableStaleLock
            ? buildFrameworkStaleCleanupCommand(releasableStaleLock, frameworkStatus.criticalChangedFiles, 'temporary framework maintenance before commit')
            : null;
    const crossFileConsistencyFindings = closeTransactionReceiptReuse.reusable
        ? []
        : checkStageTimeCrossFileConsistency({
            root,
            stagedFiles,
            isBrokerResolutionAuthorizedDependencyDeferral
        });
    const blockingTaskAuditFindings = [];
    const baseOk = encodingReport.ok
        && gitIndexDiagnostic.ok
        && blockingFrameworkIssues.length === 0
        && planningMirrorDriftFiles.length === 0
        && directionLockDriftFiles.length === 0
        && quickfixDriftFiles.length === 0
        && !quickfixFileLimitExceeded
        && !quickfixLineLimitExceeded
        && commitAttributionReport.ok
        && protectedStateReport.ok
        && emergencyUseAuditReport.ok
        && taskCardStatusReport.ok
        && sameFileClaimReport.ok
        && blockingTaskAuditFindings.length === 0
        && failedValidatorRuns.length === 0
        && crossFileConsistencyFindings.length === 0
        && actionableResidueFindings.length === 0;
    const gitHeadEvidenceRequired = shouldWriteGitHeadEvidenceForStagedCommit({
        stagedFiles,
        criticalChangedFiles: frameworkStatus.criticalChangedFiles
    });
    // TASK-AAO-0136: collect tree-wide advisory findings (warnings only, not blockers).
    const advisoryFindings = [];
    const teamGateFindings = buildTeamGateFindings(root, stagedFiles);
    const blockingFindings = [
        ...buildPreCommitBlockingFindings({
            encodingReport,
            gitIndexDiagnostic,
            blockingFrameworkIssues,
            frameworkClaimCommand,
            staleLocks,
            planningMirrorDriftFiles,
            directionLockDriftFiles,
            quickfixDriftFiles,
            quickfixFileLimitExceeded,
            quickfixLineLimitExceeded,
            quickfixChangedLineCount,
            commitAttributionFindings: commitAttributionReport.findings,
            protectedStateFindings: protectedStateReport.findings,
            emergencyUseAuditFindings: emergencyUseAuditReport.findings,
            taskCardStatusFindings: taskCardStatusReport.findings,
            sameFileClaimFindings: sameFileClaimReport.findings,
            taskAuditFindings,
            failedValidatorRuns,
            stagedFiles,
            advisoryFindingsSink: advisoryFindings,
            crossFileConsistencyFindings,
            residueFindings: actionableResidueFindings
        }),
        ...teamGateFindings
    ];
    const ok = baseOk && teamGateFindings.length === 0;
    const evidenceWrite = ok && gitHeadEvidenceRequired && !scopedIndexActive && !commitIndexFinalized
        ? writeStagedGitHeadEvidence(root, stagedFiles, commandRuns)
        : null;
    const failureEnvelope = ok
        ? null
        : buildPreCommitFailureEnvelope({
            blockingFindings,
            frameworkClaimCommand,
            gitIndexDiagnostic,
            failedValidatorRuns
        });
    const directionLockAllowedFilesWarning = directionLockAllowedFilesMismatches.length > 0
        ? message('warn', 'ATM_DIRECTION_LOCK_ALLOWED_FILES_MISMATCH', 'Active task direction lock(s) have drifted between top-level files, embedded allowedFiles, or claim.files. Canonical source is taskDirectionLock.allowedFiles.', {
            diagnoses: directionLockAllowedFilesMismatches
        })
        : null;
    return makeResult({
        ok,
        command: 'hook',
        cwd: root,
        messages: [
            ok
                ? message('info', 'ATM_HOOK_PRE_COMMIT_OK', 'ATM pre-commit hook passed and staged git-head evidence when needed.', {
                    stagedFileCount: stagedFiles.length,
                    criticalChangedFileCount: frameworkStatus.criticalChangedFiles.length,
                    gitHeadEvidenceRequired,
                    evidencePath: evidenceWrite?.evidencePath ?? null,
                    scopedIndexActive,
                    commitIndexFinalized,
                    closeTransactionReceiptReuse,
                    advisoryTreeWideFindingsCount: advisoryFindings.length
                })
                : message('error', failureEnvelope?.deferredGovernanceCandidate
                    ? 'ATM_HOOK_PRE_COMMIT_DEFERRED_GOVERNANCE_REQUIRED'
                    : 'ATM_HOOK_PRE_COMMIT_FAILED', failureEnvelope?.deferredGovernanceCandidate
                    ? 'ATM pre-commit blocked this commit on governance-state requirements; content validation did not report a failure.'
                    : 'ATM pre-commit hook blocked this commit.', {
                    encodingFindings: encodingReport.findings.length,
                    frameworkBlockers: blockingFrameworkIssues,
                    planningMirrorDriftFiles,
                    taskDirectionDriftFiles: directionLockDriftFiles,
                    quickfixDriftFiles,
                    quickfixFileLimitExceeded,
                    quickfixLineLimitExceeded,
                    quickfixChangedLineCount,
                    protectedStateFindings: protectedStateReport.findings,
                    emergencyUseAuditFindings: emergencyUseAuditReport.findings,
                    taskCardStatusFindings: taskCardStatusReport.findings,
                    sameFileClaimFindings: sameFileClaimReport.findings,
                    taskAuditFindings: taskAuditFindings.length,
                    failedValidators: failedValidatorRuns.map((entry) => entry.command),
                    gitIndexDiagnostic,
                    crossFileConsistencyFindings: crossFileConsistencyFindings.length,
                    // TASK-AAO-0136: blockingStagedFindings is the operator-facing split.
                    blockingStagedFindings: blockingFindings,
                    blockingFindings,
                    governanceStateFindings: failureEnvelope?.governanceStateFailures ?? [],
                    contentValidationFindings: failureEnvelope?.contentValidationFailures ?? [],
                    deferredGovernanceCandidate: failureEnvelope?.deferredGovernanceCandidate ?? false,
                    advisoryTreeWideFindings: advisoryFindings,
                    failureEnvelope,
                    nextStep: blockingFindings.find((entry) => entry.requiredCommand)?.requiredCommand ?? frameworkClaimCommand
                }),
            ...(directionLockAllowedFilesWarning ? [directionLockAllowedFilesWarning] : []),
            ...(explicitActorWarning ? [explicitActorWarning] : []),
            ...(autoCleanedResidue.length > 0
                ? [message('warn', 'ATM_HOOK_AUTO_CLEANED_GENERATED_RESIDUE', 'ATM auto-cleaned known generated residue before pre-commit evaluation.', {
                        autoCleanedResidue
                    })]
                : []),
            ...(advisoryFindings.length > 0
                ? [message('warn', 'ATM_HOOK_PRE_COMMIT_TREE_WIDE_ADVISORY', `Pre-commit found ${advisoryFindings.length} tree-wide task-audit finding(s) that do not affect this commit. Surfaced as advisory only.`, {
                        advisoryTreeWideFindings: advisoryFindings
                    })]
                : [])
        ],
        evidence: {
            action: 'pre-commit',
            stagedFiles,
            gitIndexDiagnostic,
            encodingReport,
            frameworkStatus,
            allowAdopterInfrastructureSync,
            blockingFrameworkIssues,
            frameworkClaimCommand,
            activeDirectionLocks,
            directionLockPlanningMirrorPaths,
            directionLockAllowedFilesDiagnoses,
            directionLockAllowedFilesMismatches,
            taskOpenImportBundle,
            planningMirrorDriftFiles,
            activeQuickfixLock,
            directionLockDriftFiles,
            quickfixDriftFiles,
            quickfixFileLimitExceeded,
            quickfixLineLimitExceeded,
            quickfixChangedLineCount,
            commitAttributionReport,
            protectedStateReport,
            emergencyUseAuditReport,
            taskCardStatusReport,
            sameFileClaimReport,
            closeTransactionReceiptReuse,
            taskAudit: {
                executionPlane: 'deferred',
                requiredBy: ['taskflow auto-evidence', 'pre-push', 'CI'],
                findings: taskAuditFindings
            },
            commandRuns,
            blockingFindings,
            crossFileConsistencyFindings,
            autoCleanedResidue,
            residueReport,
            failureEnvelope,
            gitHeadEvidenceRequired,
            evidenceWrite
        }
    });
}
